// Fetch commits, closed issues and merged PRs for the past 7 days
const config = $('Config').item.json;
const repo = config.GITHUB_REPO;
const token = config.GITHUB_TOKEN;
const language = config.LANGUAGE || 'EN';

const now = new Date();
const since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const sinceISO = since.toISOString();
const weekLabel = `${sinceISO.split('T')[0]} → ${now.toISOString().split('T')[0]}`;

const headers = {
  'Authorization': `token ${token}`,
  'Accept': 'application/vnd.github.v3+json',
  'User-Agent': 'n8n-weekly-summary-bot'
};

// 1. Fetch commits
const commitsResp = await fetch(
  `https://api.github.com/repos/${repo}/commits?since=${encodeURIComponent(sinceISO)}&per_page=100`,
  { headers }
);
if (!commitsResp.ok) throw new Error(`GitHub commits error: ${commitsResp.status} ${await commitsResp.text()}`);
const commits = await commitsResp.json();

// 2. Fetch closed issues (excluding PRs)
const issuesResp = await fetch(
  `https://api.github.com/repos/${repo}/issues?state=closed&since=${encodeURIComponent(sinceISO)}&per_page=100`,
  { headers }
);
if (!issuesResp.ok) throw new Error(`GitHub issues error: ${issuesResp.status} ${await issuesResp.text()}`);
const allIssues = await issuesResp.json();
const issues = Array.isArray(allIssues) ? allIssues.filter(i => !i.pull_request) : [];

// 3. Fetch merged PRs
const prsResp = await fetch(
  `https://api.github.com/repos/${repo}/pulls?state=closed&per_page=100&sort=updated&direction=desc`,
  { headers }
);
if (!prsResp.ok) throw new Error(`GitHub PRs error: ${prsResp.status} ${await prsResp.text()}`);
const allPRs = await prsResp.json();
const mergedPRs = Array.isArray(allPRs)
  ? allPRs.filter(pr => pr.merged_at && new Date(pr.merged_at) >= since)
  : [];

// Format for Claude prompt
const commitList = commits.length > 0
  ? commits.slice(0, 30).map(c =>
      `- [${c.sha.substring(0, 7)}] ${c.commit.message.split('\n')[0]} (${c.commit.author.name})`
    ).join('\n')
  : '(no commits this week)';

const issueList = issues.length > 0
  ? issues.slice(0, 20).map(i => `- #${i.number}: ${i.title}`).join('\n')
  : '(no issues closed this week)';

const prList = mergedPRs.length > 0
  ? mergedPRs.slice(0, 20).map(pr => `- #${pr.number}: ${pr.title} by @${pr.user.login}`).join('\n')
  : '(no PRs merged this week)';

const langInstruction = language === 'FR'
  ? 'Rédige le résumé en FRANÇAIS avec un ton professionnel mais accessible.'
  : 'Write the summary in ENGLISH with a professional yet approachable tone.';

const prompt = `You are a technical writer creating a weekly development summary.\n${langInstruction}\n\nRepository: ${repo}\nWeek: ${weekLabel}\n\n## Commits this week (${commits.length} total)\n${commitList}\n\n## Issues closed this week (${issues.length} total)\n${issueList}\n\n## Pull Requests merged this week (${mergedPRs.length} total)\n${prList}\n\nGenerate a concise narrative summary (300-500 words) that:\n1. Opens with a one-sentence overview of the week\n2. Highlights the most impactful features, fixes, and improvements\n3. Mentions key resolved issues\n4. Closes with a brief forward-looking sentence\n\nUse markdown formatting with bold for important points. Be specific and concrete.`;

const claudeBody = JSON.stringify({
  model: 'claude-sonnet-4-20250514',
  max_tokens: 1500,
  messages: [{ role: 'user', content: prompt }]
});

return [{
  json: {
    repo,
    weekLabel,
    language,
    commitCount: commits.length,
    issueCount: issues.length,
    prCount: mergedPRs.length,
    claudeBody,
    ANTHROPIC_API_KEY: config.ANTHROPIC_API_KEY,
    DISCORD_WEBHOOK_URL: config.DISCORD_WEBHOOK_URL
  }
}];

// Format Claude's response into a Discord embed
const claudeData = $input.item.json;
const githubData = $('Fetch GitHub Data').item.json;

// Extract summary text from Claude response
const summaryText = (claudeData.content && Array.isArray(claudeData.content) && claudeData.content[0])
  ? claudeData.content[0].text
  : 'Failed to generate summary. Please check your Anthropic API key and model name.';

// Discord embed description limit: 4096 chars
const description = summaryText.length > 4000
  ? summaryText.substring(0, 3997) + '...'
  : summaryText;

const langEmoji = githubData.language === 'FR' ? '🇫🇷' : '🇺🇸';

const discordPayload = {
  username: '📊 Weekly Dev Bot',
  embeds: [
    {
      title: `📝 Weekly Dev Summary — ${githubData.repo}`,
      description: description,
      color: 7506394,
      fields: [
        {
          name: '📦 Commits',
          value: String(githubData.commitCount),
          inline: true
        },
        {
          name: '🔧 Issues Closed',
          value: String(githubData.issueCount),
          inline: true
        },
        {
          name: '🔀 PRs Merged',
          value: String(githubData.prCount),
          inline: true
        },
        {
          name: `📅 Period ${langEmoji}`,
          value: githubData.weekLabel,
          inline: false
        }
      ],
      footer: {
        text: 'Generated by n8n + Claude claude-sonnet-4-20250514 · Weekly Dev Summary'
      },
      timestamp: new Date().toISOString()
    }
  ]
};

return [{
  json: {
    discordPayload: JSON.stringify(discordPayload),
    DISCORD_WEBHOOK_URL: githubData.DISCORD_WEBHOOK_URL,
    summaryPreview: summaryText.substring(0, 200)
  }
}];
